<?php require 'config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$role=trim($_POST['role']??'');if($name!==''){$pdo->prepare("INSERT INTO staff(name,role) VALUES(?,?)")->execute([$name,$role]);header('Location:index.php#staff');exit;}} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><link rel="stylesheet" href="assets/style.css"><title>Add staff | CareTrack</title></head><body><main class="form-page"><a href="index.php">← Dashboard</a><section class="panel"><h1>Add staff member</h1><form method="post"><label>Full name<input name="name" required></label><label>Role<input name="role" placeholder="Caregiver, coordinator..."></label><button class="button">Save staff</button></form></section></main></body></html>